@Bean
IntegrationFlow orders() {
    return IntegrationFlow.from("orders")
        .routeToRecipients(r -> r
            .applySequence(true)          // stamp sequence so downstream can correlate
            .ignoreSendFailures(false)
            .sendTimeout(1_000L)
            .recipient("billing")
            .recipient("inventory"))
        .get();
}

